def transform(g):
    H,W=len(g),len(g[0])
    block=2
    cells=[(i,j) for i in range(H) for j in range(W) if g[i][j]==block]
    top=min(i for i,j in cells); bot=max(i for i,j in cells)
    left=min(j for i,j in cells); right=max(j for i,j in cells)
    markers={(i,j) for i in range(H) for j in range(W) if g[i][j] not in (0,block)}
    out=[row[:] for row in g]
    for i,j in cells: out[i][j]=block
    for i in range(top,bot+1):
        ml=[j for (r,j) in markers if r==i and j<left]
        mr=[j for (r,j) in markers if r==i and j>right]
        if not mr: j0=right+1
        else: j0=None
        if j0 is not None:
            for j in range(j0,W):
                if (i,j) in markers: break
                out[i][j]=block
        if not ml:
            for j in range(left-1,-1,-1):
                if (i,j) in markers: break
                out[i][j]=block
    for j in range(left,right+1):
        mu=[i for (i,c) in markers if c==j and i<top]
        md=[i for (i,c) in markers if c==j and i>bot]
        if not md:
            for i in range(bot+1,H):
                if (i,j) in markers: break
                out[i][j]=block
        if not mu:
            for i in range(top-1,-1,-1):
                if (i,j) in markers: break
                out[i][j]=block
    return out

